css:
.mz *,.mz *::before,.mz *::after{box-sizing: border-box; margin: 0; padding: 0;}
.mz .recuerda{border: 2px solid var(--bosque); border-radius: 10px; padding: 6px 12px; margin-bottom: 8px;}
.mz .recuerda-titulo{font-size: 13px; font-weight: 700; font-family: sans-serif; margin-bottom: 4px;}
.mz .rec-texto{font-size: 14px; line-height: 1.4;}
.mz .rec-texto b{font-size: 16px;}
.mz .rec-op{font-size: 18px; font-weight: 700; font-family: sans-serif; white-space: nowrap;}
.mz .rec-op .x{font-size: 20px;}
.mz .tablas-fila{display: flex; gap: 30px; flex-wrap: wrap; justify-content: center;}
.mz .tabla-mult{display: grid; grid-template-columns: repeat(2, auto); gap: 5px 26px; border: 1.8px solid var(--bosque); border-radius: 11px; padding: 8px 16px;}
.mz .tabla-mult .titulo{grid-column: 1 / -1; text-align: center; font-size: 14px; font-weight: 700; font-family: sans-serif; border-bottom: 1.5px solid var(--bosque); padding-bottom: 3px; margin-bottom: 2px;}
.mz .reng{display: flex; align-items: center; gap: 6px; font-size: 16px; font-weight: 700; font-family: sans-serif;}
.mz .caja{width: 44px; height: 27px; border: 1.6px solid var(--bosque); border-radius: 6px; display: inline-block;}
.mz .reng .op{min-width: 56px; text-align: right;}
.mz .calc-grid{display: grid; grid-template-columns: repeat(2, 1fr); gap: 8px 34px;}
.mz .resp-fila{display: flex; align-items: center; gap: 7px; font-size: 18px; font-weight: 700; font-family: sans-serif; flex-wrap: wrap;}
.mz .resp-fila .lead{min-width: 78px;}
.mz .pista{font-family: sans-serif; font-size: 11.5px; font-weight: 600; color: #555; margin: -3px 0 7px;}
.mz .rec-texto{line-height: 1.725 !important;}
